import java.io.StringReader;
import org.apache.commons.io.input.UnsynchronizedBufferedReader;
public class TestReady {
    public static void main(String[] args) throws Exception {
        UnsynchronizedBufferedReader r = new UnsynchronizedBufferedReader(new StringReader("a"));
        System.out.println("before: " + r.ready());
        r.read();
        System.out.println("after read: " + r.ready());
        r.close();
        try {
            r.ready();
            System.out.println("ready after close: no exception");
        } catch (Exception e) {
            System.out.println("ready after close threw: " + e);
        }
    }
}
